private static SAXParser newSAXParser() throws TikaException {
    SAXParserFactory factory = SAXParserFactory.newInstance();
    factory.setNamespaceAware(false);
    try {
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
    } catch (ParserConfigurationException | SAXException e) {
        LOG.warn("can't set secure processing feature on: " + factory.getClass() + ". User assumes responsibility for consequences.");
    }
    try {
        return factory.newSAXParser();
    } catch (ParserConfigurationException | SAXException e) {
        throw new TikaException("Can't create new sax parser", e);
    }
}
